import { test, expect } from '@playwright/test';

test.describe('Table Row Highlight on Hover', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should highlight a row when hovering over it', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify table headers are visible
    const headers = page.getByRole('rowheader');
    await expect(headers).toBeVisible();

    // Verify first row is visible
    const firstRow = page.getByRole('row', { name: /row 1/i });
    await expect(firstRow).toBeVisible();

    // Verify first cell is visible
    const firstCell = page.getByRole('cell', { name: /cell 1/i });
    await expect(firstCell).toBeVisible();

    // Verify row is not highlighted initially
    const rowStyles = page.getByRole('row', { name: /row 1/i }).evaluate((el) => {
      const style = getComputedStyle(el);
      return style.backgroundColor;
    });
    await expect(rowStyles).not.toBe('rgb(255, 255, 255)');

    // Hover over the first row
    await firstRow.hover();

    // Verify row is highlighted
    const highlightedRowStyles = page.getByRole('row', { name: /row 1/i }).evaluate((el) => {
      const style = getComputedStyle(el);
      return style.backgroundColor;
    });
    await expect(highlightedRowStyles).toBe('rgb(255, 255, 255)');

    // Verify first cell is highlighted
    const highlightedFirstCell = page.getByRole('cell', { name: /cell 1/i });
    await expect(highlightedFirstCell).toHaveClass(/highlight/);

    // Verify hover state is active
    const hoverState = page.getByRole('row', { name: /row 1/i }).evaluate((el) => {
      const style = getComputedStyle(el);
      return style.hoverState;
    });
    await expect(hoverState).toBe('hovered');

    // Verify row is not highlighted when not hovered
    await expect(page.getByRole('row', { name: /row 1/i })).not.toHaveClass(/highlight/);
  });

  test('should unhighlight a row when hovering off', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify table headers are visible
    const headers = page.getByRole('rowheader');
    await expect(headers).toBeVisible();

    // Verify first row is visible
    const firstRow = page.getByRole('row', { name: /row 1/i });
    await expect(firstRow).toBeVisible();

    // Verify first cell is visible
    const firstCell = page.getByRole('cell', { name: /cell 1/i });
    await expect(firstCell).toBeVisible();

    // Hover over the first row
    await firstRow.hover();

    // Verify row is highlighted
    const highlightedRowStyles = page.getByRole('row', { name: /row 1/i }).evaluate((el) => {
      const style = getComputedStyle(el);
      return style.backgroundColor;
    });
    await expect(highlightedRowStyles).toBe('rgb(255, 255, 255)');

    // Verify first cell is highlighted
    const highlightedFirstCell = page.getByRole('cell', { name: /cell 1/i });
    await expect(highlightedFirstCell).toHaveClass(/highlight/);

    // Verify hover state is active
    const hoverState = page.getByRole('row', { name: /row 1/i }).evaluate((el) => {
      const style = getComputedStyle(el);
      return style.hoverState;
    });
    await expect(hoverState).toBe('hovered');

    // Hover off the first row
    await firstRow.unhover();

    // Verify row is unhighlighted
    await expect(page.getByRole('row', { name: /row 1/i })).not.toHaveClass(/highlight/);

    // Verify hover state is not active
    const hoverState = page.getByRole('row', { name: /row 1/i }).evaluate((el) => {
      const style = getComputedStyle(el);
      return style.hoverState;
    });
    await expect(hoverState).not.toBe('hovered');
  });
});
